# Capitan Ohm. Before the badge: the camera cuts to him, his challenge, the fight (trainer ohm: Spoolt 21, Zaphid 18, Voltgecko 24); a win = his speech, the Medalla Voltio
# (flag 82, the trainer card's third badge), what it is, then Disc 04 (a full bag keeps ohm_disc clear and he hands it over the next time you talk to him). A loss is the blackout. Afterwards a last line.
@script ohm npc
    jf badge_voltio after
    npc_face_hero ohm
    cam_npc ohm
    say dinamo.ohm.pre
    battle 47 0
    jv 0 1 won
    blackout
    end
  won:
    say dinamo.ohm.win
    setf badge_voltio
    say dinamo.badge
    say dinamo.ohm.about
    call ohm_gift
    cam_hero
    end
  after:
    npc_face_hero ohm
    cam_npc ohm
    jf ohm_disc said
    call ohm_gift
    cam_hero
    end
  said:
    say dinamo.ohm.after
    cam_hero
@end
@script ohm_gift called
    say dinamo.ohm.disc
    give_item disc_04 1
    jv 0 0 full
    item_var 0 disc_04
    say gl.gift
    setf ohm_disc
    say dinamo.ohm.disc_about
    end
  full:
    say gl.found.full
@end
